class MinStack {
  constructor() {
    this.items = []
    this.mins = []
  }

  push(x) {
    this.items.push(x)
    this.mins.push(this.mins.length ? Math.min(x, this.mins[this.mins.length - 1]) : x)
  }

  pop() {
    this.items.pop()
    this.mins.pop()
  }

  top() {
    return this.items[this.items.length - 1]
  }

  min() {
    return this.mins[this.mins.length - 1]
  }
}

