class MinStack:
    def __init__(self):
        self.items = []
        self.mins = []

    def push(self, x):
        self.items.append(x)
        self.mins.append(x if not self.mins else min(x, self.mins[-1]))

    def pop(self):
        self.items.pop()
        self.mins.pop()

    def top(self):
        return self.items[-1]

    def min(self):
        return self.mins[-1]


# Test driver: replays ops and collects each method's return value (None for push/pop).
def run_min_stack(ops):
    stack = MinStack()
    out = []
    for op, *args in ops:
        out.append(getattr(stack, op)(*args))
    return out
